window.__QUIZ_CHUNKS__.B2 = {"B2":{"vocab":[{"id":"q-vocab-b2-0001","level":"B2","skill":"vocab","prompt":"「la garde alternée」的意思是：","options":["轮流抚养（离异父母轮流照顾孩子）","隔代抚养","全职保姆","家庭津贴"],"answer":"轮流抚养（离异父母轮流照顾孩子）","explain":"garde alternée 指离异父母轮流照顾子女；隔代抚养是 élevé par les grands-parents，保姆是 nourrice，家庭津贴是 allocations familiales。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-b2-0002","level":"B2","skill":"vocab","prompt":"「la solidarité intergénérationnelle」的意思是：","options":["代际互助","家庭暴力","世代冲突","家庭遗产"],"answer":"代际互助","explain":"intergénérationnel 指代际之间的；世代冲突是 conflit de générations，家庭遗产是 héritage familial，家庭暴力是 violence familiale。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-b2-0003","level":"B2","skill":"vocab","prompt":"「le système immunitaire」的意思是：","options":["免疫系统","神经系统","消化系统","呼吸系统"],"answer":"免疫系统","explain":"immunitaire 来自 immunité（免疫）；神经系统是 système nerveux，消化系统是 système digestif，呼吸系统是 système respiratoire。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-b2-0004","level":"B2","skill":"vocab","prompt":"「un traitement de fond」的意思是：","options":["针对病因的长期基础治疗","紧急抢救","止痛药","手术方案"],"answer":"针对病因的长期基础治疗","explain":"traitement de fond 指针对病因的持续治疗；紧急抢救是 soins d'urgence，止痛药是 antidouleur，手术方案是 plan opératoire。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-b2-0005","level":"B2","skill":"vocab","prompt":"「un logement insalubre」的意思是：","options":["卫生条件极差、有损健康的住房","廉租房","空置房","豪华住房"],"answer":"卫生条件极差、有损健康的住房","explain":"insalubre 指有损健康的、不卫生的；廉租房是 logement social（HLM），空置房是 logement vacant，豪华住房是 logement de luxe。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-b2-0006","level":"B2","skill":"vocab","prompt":"「la spéculation immobilière」的意思是：","options":["房地产投机","房产中介","住房补贴","旧房翻新"],"answer":"房地产投机","explain":"spéculation 是投机买卖，immobilier 是房地产；房产中介是 agence immobilière，住房补贴是 aide au logement，旧房翻新是 rénovation。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-b2-0007","level":"B2","skill":"vocab","prompt":"「la sécurité alimentaire」的意思是：","options":["食品安全","饮食自由","食品价格","食品进口"],"answer":"食品安全","explain":"sécurité alimentaire 指食品供应与食品安全；食品价格是 prix alimentaires，食品进口是 importations alimentaires，饮食自由不是法语固定表达。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-b2-0008","level":"B2","skill":"vocab","prompt":"「un produit de saison」的意思是：","options":["时令产品","加工食品","有机食品","进口食品"],"answer":"时令产品","explain":"de saison 指当季的；加工食品是 produit transformé，有机食品是 produit bio，进口食品是 produit importé。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-b2-0009","level":"B2","skill":"vocab","prompt":"「la mobilité douce」的意思是：","options":["慢行交通（步行、骑行等）","无障碍出行","公共交通","拼车"],"answer":"慢行交通（步行、骑行等）","explain":"mobilité douce 指步行、自行车等低污染出行方式；无障碍出行是 accessibilité，公共交通是 transports en commun，拼车是 covoiturage。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-b2-0010","level":"B2","skill":"vocab","prompt":"「une zone piétonne」的意思是：","options":["步行区","收费停车区","工业区","住宅区"],"answer":"步行区","explain":"piétonne 意为行人的（piéton 行人）；收费停车区是 zone de stationnement payant，工业区是 zone industrielle，住宅区是 zone résidentielle。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-b2-0011","level":"B2","skill":"vocab","prompt":"「le télétravail」的意思是：","options":["远程办公","兼职工作","实习","加班"],"answer":"远程办公","explain":"télétravail 指在家或异地远程工作；兼职是 travail à temps partiel，实习是 stage，加班是 heures supplémentaires。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-b2-0012","level":"B2","skill":"vocab","prompt":"「une reconversion professionnelle」的意思是：","options":["职业转型","职业培训","升职","提前退休"],"answer":"职业转型","explain":"reconversion 指换行业、转行；职业培训是 formation professionnelle，升职是 promotion，提前退休是 retraite anticipée。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-b2-0013","level":"B2","skill":"vocab","prompt":"「la formation continue」的意思是：","options":["继续教育（在职进修）","义务教育","远程教育","精英教育"],"answer":"继续教育（在职进修）","explain":"formation continue 指在职人员的后续培训；义务教育是 scolarité obligatoire，远程教育是 enseignement à distance，精英教育是 formation d'excellence。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-b2-0014","level":"B2","skill":"vocab","prompt":"「un cursus universitaire」的意思是：","options":["大学学业与课程体系","大学校园","大学毕业证","大学学费"],"answer":"大学学业与课程体系","explain":"cursus 指学业的阶段与课程安排；校园是 campus，毕业证是 diplôme，学费是 frais de scolarité。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-b2-0015","level":"B2","skill":"vocab","prompt":"「une infime minorité」的意思是：","options":["极少数","绝大多数","半数","少数中的多数"],"answer":"极少数","explain":"infime 意为极小的，minorité 是少数派；绝大多数是 grande majorité，半数是 la moitié。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-b2-0016","level":"B2","skill":"vocab","prompt":"「le seuil de rentabilité」的意思是：","options":["盈亏平衡点","利润率","营业额","成本上限"],"answer":"盈亏平衡点","explain":"seuil 是门槛、临界值，rentabilité 是盈利能力；利润率是 marge，营业额是 chiffre d'affaires，成本上限是 plafond de coûts。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-b2-0017","level":"B2","skill":"vocab","prompt":"「des intempéries」的意思是：","options":["恶劣天气","恒温气候","季节交替","天气预报表"],"answer":"恶劣天气","explain":"intempéries 指暴风雨等恶劣天气现象；季节交替是 changement de saison，天气预报是 bulletin météo，恒温气候不是该词含义。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-b2-0018","level":"B2","skill":"vocab","prompt":"「la fonte des glaces」的意思是：","options":["冰川融化","冰川形成","海平面下降","极地考察"],"answer":"冰川融化","explain":"fonte 是融化，glaces 是冰；形成是 formation des glaces，海平面下降是 baisse du niveau de la mer，极地考察是 expédition polaire。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-b2-0019","level":"B2","skill":"vocab","prompt":"「l'intelligence artificielle」的意思是：","options":["人工智能","人工合成材料","智能家居","自动生产线"],"answer":"人工智能","explain":"intelligence artificielle（IA）是人工智能；智能家居是 domotique，自动生产线是 chaîne de production automatisée，人工合成材料是 matériau synthétique。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-b2-0020","level":"B2","skill":"vocab","prompt":"「une cyberattaque」的意思是：","options":["网络攻击","网络广告","网络谣言","网络赌博"],"answer":"网络攻击","explain":"cyberattaque 指针对信息系统的攻击；网络广告是 publicité en ligne，网络谣言是 rumeur en ligne，网络赌博是 jeux d'argent en ligne。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-b2-0021","level":"B2","skill":"vocab","prompt":"「la liberté de la presse」的意思是：","options":["新闻自由","免费报纸","报刊订阅","媒体审查"],"answer":"新闻自由","explain":"liberté de la presse 指新闻出版自由；免费报纸是 journal gratuit，报刊订阅是 abonnement，媒体审查是 censure des médias。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-b2-0022","level":"B2","skill":"vocab","prompt":"「un débat contradictoire」的意思是：","options":["观点交锋的辩论","单方面声明","辩论赛冠军","圆桌会议"],"answer":"观点交锋的辩论","explain":"contradictoire 指有对立双方交锋；单方面声明是 déclaration unilatérale，圆桌会议是 table ronde，辩论赛冠军是 vainqueur du concours d'éloquence。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-b2-0023","level":"B2","skill":"vocab","prompt":"「le dopage」的意思是：","options":["使用兴奋剂","赛前训练","体育赞助","裁判误判"],"answer":"使用兴奋剂","explain":"dopage 指使用违禁药物提高成绩；赛前训练是 préparation, 体育赞助是 sponsoring, 裁判误判是 erreur d'arbitrage。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-b2-0024","level":"B2","skill":"vocab","prompt":"「une manifestation sportive」的意思是：","options":["体育赛事活动","体育场馆","体育俱乐部","体育用品"],"answer":"体育赛事活动","explain":"manifestation 指有组织的公开活动；场馆是 équipement sportif，俱乐部是 club，体育用品是 articles de sport。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-b2-0025","level":"B2","skill":"vocab","prompt":"「être partagé entre deux solutions」的意思是：","options":["在两种方案之间犹豫不决","同时采用两种方案","反对两种方案","赞成两种方案"],"answer":"在两种方案之间犹豫不决","explain":"être partagé 表内心矛盾、举棋不定；同时采用是 adopter les deux，反对是 rejeter，赞成是 approuver。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-b2-0026","level":"B2","skill":"vocab","prompt":"「un enthousiasme modéré」的意思是：","options":["有限度的热情","极大的热情","完全的冷淡","虚伪的奉承"],"answer":"有限度的热情","explain":"modéré 意为适度的、有限的；极大的热情是 enthousiasme débordant，冷淡是 indifférence，奉承是 flatterie。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-b2-0027","level":"B2","skill":"vocab","prompt":"「les inégalités sociales」的意思是：","options":["社会不平等","社会流动性","社会阶层固化","社会救助"],"answer":"社会不平等","explain":"inégalités 指不平等现象；社会流动性是 mobilité sociale，阶层固化是 reproduction sociale，社会救助是 aide sociale。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-b2-0028","level":"B2","skill":"vocab","prompt":"「l'intégration des immigrés」的意思是：","options":["移民融入","移民遣返","移民配额","移民聚居"],"answer":"移民融入","explain":"intégration 指融入社会；遣返是 reconduite à la frontière，配额是 quotas，聚居是 regroupement communautaire。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-b2-0029","level":"B2","skill":"vocab","prompt":"「la transition écologique」的意思是：","options":["生态转型","生态破坏","垃圾分类","环保认证标识"],"answer":"生态转型","explain":"transition écologique 指向可持续模式转变；生态破坏是 destruction des écosystèmes，垃圾分类是 tri des déchets，环保认证是 label environnemental。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-b2-0030","level":"B2","skill":"vocab","prompt":"「la biodiversité menacée」的意思是：","options":["受到威胁的生物多样性","生物实验室","物种引进","森林采伐"],"answer":"受到威胁的生物多样性","explain":"biodiversité 是生物多样性，menacée 指受到威胁的；物种引进是 introduction d'espèces，森林采伐是 déforestation。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-b2-0031","level":"B2","skill":"vocab","prompt":"「la séparation des pouvoirs」的意思是：","options":["权力分立","政权更替","权力下放","政党联盟"],"answer":"权力分立","explain":"séparation des pouvoirs 指立法、行政、司法三权分立；政权更替是 alternance，权力下放是 décentralisation，政党联盟是 coalition。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-b2-0032","level":"B2","skill":"vocab","prompt":"「une disposition légale」的意思是：","options":["一项法律规定（条款）","一次法律诉讼","一份法律合同","一个法律漏洞"],"answer":"一项法律规定（条款）","explain":"disposition 在此指法律条款；诉讼是 procès，合同是 contrat，法律漏洞是 vide juridique。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-b2-0033","level":"B2","skill":"vocab","prompt":"「la dette publique」的意思是：","options":["公共债务","公共开支","财政赤字","国民收入"],"answer":"公共债务","explain":"dette publique 指国家累积的债务；公共开支是 dépenses publiques，财政赤字是 déficit budgétaire，国民收入是 revenu national。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-b2-0034","level":"B2","skill":"vocab","prompt":"「la relance économique」的意思是：","options":["经济复苏与刺激政策","经济衰退","经济封锁","经济预测"],"answer":"经济复苏与刺激政策","explain":"relance 指刺激增长、重启经济；衰退是 récession，封锁是 embargo，预测是 prévisions économiques。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-b2-0035","level":"B2","skill":"vocab","prompt":"「le mécénat culturel」的意思是：","options":["文化赞助","文化审查","文化遗产保护","文化输出"],"answer":"文化赞助","explain":"mécénat 指企业或个人对文化事业的资助；审查是 censure，遗产保护是 protection du patrimoine，文化输出是 diffusion culturelle。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-b2-0036","level":"B2","skill":"vocab","prompt":"「une œuvre engagée」的意思是：","options":["有社会立场的作品","未完成的作品","匿名作品","商业订单作品"],"answer":"有社会立场的作品","explain":"engagée 指艺术家主动介入社会议题；未完成是 inachevée，匿名是 anonyme，商业订单是 commande commerciale。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-b2-0037","level":"B2","skill":"vocab","prompt":"「nuancer un jugement」的意思是：","options":["让判断更细致、不绝对化","强化判断","撤回判断","重复判断"],"answer":"让判断更细致、不绝对化","explain":"nuancer 指加进细微差别、避免绝对；强化是 renforcer，撤回是 retirer，重复是 répéter。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-b2-0038","level":"B2","skill":"vocab","prompt":"「à défaut de preuves」的意思是：","options":["由于缺乏证据","因为有充分证据","为了寻找证据","除了证据之外"],"answer":"由于缺乏证据","explain":"à défaut de ＝「在没有……的情况下」；充分证据是 preuves suffisantes，寻找证据是 chercher des preuves，除了是 hormis。","source":"词汇 · 二十四、抽象概念与逻辑（concepts abstraits） · vocab.html#t24-titre"},{"id":"q-vocab-b2-0039","level":"B2","skill":"vocab","prompt":"「force est de constater que」的意思是：","options":["不得不承认","必须继续","应当核实","有理由拒绝"],"answer":"不得不承认","explain":"force est de constater que 是书面固定表达，意为「只得承认」；必须继续是 il faut poursuivre，应当核实是 il convient de vérifier，有理由拒绝是 il y a lieu de refuser。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"},{"id":"q-vocab-b2-0040","level":"B2","skill":"vocab","prompt":"「mettre en lumière un phénomène」的意思是：","options":["阐明、揭示一个现象","隐瞒一个现象","夸大一个现象","复制一个现象"],"answer":"阐明、揭示一个现象","explain":"mettre en lumière 是使……显现、阐明；隐瞒是 dissimuler，夸大是 exagérer，复制是 reproduire。","source":"词汇 · 二十五、高频动词与万能表达（verbes fréquents） · vocab.html#t25-titre"}],"grammar":[{"id":"q-gram-b2-0001","level":"B2","skill":"grammar","prompt":"Il ___ la porte et sortit.（ouvrir，简单过去时）","options":["ouvrit","ouvra","ouvrait","a ouvert"],"answer":"ouvrit","explain":"简单过去时用于书面叙事，ouvrir 的第三人称单数简单过去时为 ouvrit（-ir 类常以 -it 结尾）；ouvra 是把第一组 -er 词尾套在第二组动词上的错误，ouvrait 是未完成过去时，a ouvert 是口语体的复合过去时。","source":"语法点 · 简单过去时（le passé simple） · grammar-b1b2.html#passe-simple"},{"id":"q-gram-b2-0002","level":"B2","skill":"grammar","prompt":"Ils ___ que tout était perdu.（comprendre，简单过去时）","options":["comprirent","comprendirent","comprenaient","ont compris"],"answer":"comprirent","explain":"comprendre 的 ils 简单过去时是 comprirent；comprendirent 是臆造形式，comprenaient 是未完成过去时，ont compris 是复合过去时。","source":"语法点 · 简单过去时（le passé simple） · grammar-b1b2.html#passe-simple"},{"id":"q-gram-b2-0003","level":"B2","skill":"grammar","prompt":"Je suis content que tu ___ ton examen.（已经通过）","options":["aies réussi","réussisses","as réussi","réussiras"],"answer":"aies réussi","explain":"从句动作在主句之前已完成，用虚拟式过去时（avoir 的虚拟式 + 过去分词）：aies réussi；réussisses 是虚拟式现在时（表同时或将来），as réussi 是直陈式，réussiras 是将来时。","source":"语法点 · 虚拟式过去时（le subjonctif passé） · grammar-b1b2.html#subj-passe"},{"id":"q-gram-b2-0004","level":"B2","skill":"grammar","prompt":"Il est possible que le train ___ déjà parti.","options":["soit","parte","est","partira"],"answer":"soit","explain":"déjà 表明动作已完成，要用虚拟式过去时（être 的虚拟式 + 过去分词）：soit parti（partir 用 être 且配合）；parte 是虚拟式现在时，不能与 déjà 表已完成，est 是直陈式，partira 是将来时。","source":"语法点 · 虚拟式过去时（le subjonctif passé） · grammar-b1b2.html#subj-passe"},{"id":"q-gram-b2-0005","level":"B2","skill":"grammar","prompt":"Bien qu'il ___ son travail, il continue à rester au bureau.（已经完成）","options":["ait fini","finisse","a fini","finira"],"answer":"ait fini","explain":"让步从句的动作已完成（交完工作仍留在办公室），用虚拟式过去时 ait fini；finisse 是虚拟式现在时（表未完成），a fini 是直陈式，finira 是将来时。","source":"语法点 · 虚拟式过去时（le subjonctif passé） · grammar-b1b2.html#subj-passe"},{"id":"q-gram-b2-0006","level":"B2","skill":"grammar","prompt":"Je crois qu'il ___ raison, mais je ne crois pas qu'il ___ toutes les données.","options":["a / ait","ait / a","a / a","ait / ait"],"answer":"a / ait","explain":"croire 的肯定句用直陈式（a raison），否定句改用虚拟式（ait toutes les données）；其余组合把语式弄反或都用了同一种语式。","source":"语法点 · 虚拟式 vs 直陈式（subjonctif ou indicatif） · grammar-b1b2.html#subj-vs-indicatif"},{"id":"q-gram-b2-0007","level":"B2","skill":"grammar","prompt":"Il est probable qu'il ___ demain, mais il est possible qu'il ___ .","options":["viendra / vienne","vienne / viendra","viendra / viendra","vienne / vienne"],"answer":"viendra / vienne","explain":"probable 表较高可能性，用直陈式；possible 表不确定，用虚拟式；两组语式不能互换或统一。","source":"语法点 · 虚拟式 vs 直陈式（subjonctif ou indicatif） · grammar-b1b2.html#subj-vs-indicatif"},{"id":"q-gram-b2-0008","level":"B2","skill":"grammar","prompt":"Quoiqu'il ___ jeune, il est très expérimenté.","options":["soit","est","sera","était"],"answer":"soit","explain":"quoique（虽然）后必须用虚拟式 soit；est、sera、était 是直陈式，只能跟在 même si 之类连词后。","source":"语法点 · 虚拟式 vs 直陈式（subjonctif ou indicatif） · grammar-b1b2.html#subj-vs-indicatif"},{"id":"q-gram-b2-0009","level":"B2","skill":"grammar","prompt":"Je resterai ici jusqu'à ce qu'il ___ .（revenir）","options":["revienne","revient","reviendra","revenait"],"answer":"revienne","explain":"jusqu'à ce que 后必须用虚拟式 revienne；直陈式形式与这个连词不搭配（同义的 jusqu'au moment où 才用直陈式）。","source":"语法点 · 虚拟式连词（les conjonctions + subjonctif） · grammar-b1b2.html#subj-conjonctions"},{"id":"q-gram-b2-0010","level":"B2","skill":"grammar","prompt":"À moins qu'il ___ , nous partirons sans lui.（pleuvoir）","options":["pleuve","pleut","pleuvra","pleuvait"],"answer":"pleuve","explain":"à moins que（除非）后接虚拟式 pleuve；pleut、pleuvra、pleuvait 都是直陈式，不能用于这个连词。","source":"语法点 · 虚拟式连词（les conjonctions + subjonctif） · grammar-b1b2.html#subj-conjonctions"},{"id":"q-gram-b2-0011","level":"B2","skill":"grammar","prompt":"Donne-moi ton numéro pour que je ___ te joindre.","options":["puisse","peux","pourrai","pouvais"],"answer":"puisse","explain":"pour que 引导目的从句，用虚拟式 puisse；peux、pourrai、pouvais 都是直陈式。","source":"语法点 · 虚拟式连词（les conjonctions + subjonctif） · grammar-b1b2.html#subj-conjonctions"},{"id":"q-gram-b2-0012","level":"B2","skill":"grammar","prompt":"J'___ venir, mais j'étais malade.（vouloir，未实现的意愿）","options":["aurais voulu","voulais","voudrais","ai voulu"],"answer":"aurais voulu","explain":"条件式过去时表未实现的意愿与遗憾：j'aurais voulu venir；voulais 是未完成过去时，voudrais 是条件式现在时，ai voulu 是复合过去时（表事实）。","source":"语法点 · 条件式过去时（le conditionnel passé） · grammar-b1b2.html#cond-passe"},{"id":"q-gram-b2-0013","level":"B2","skill":"grammar","prompt":"Tu ___ me prévenir !（pouvoir，责备）","options":["aurais pu","pouvais","pourrais","as pu"],"answer":"aurais pu","explain":"条件式过去时表责备「你本可以（却没有）」：tu aurais pu me prévenir；pouvais 是未完成过去时，pourrais 是条件式现在时，as pu 是复合过去时。","source":"语法点 · 条件式过去时（le conditionnel passé） · grammar-b1b2.html#cond-passe"},{"id":"q-gram-b2-0014","level":"B2","skill":"grammar","prompt":"Selon le journal, le vol ___ reporté.（未经证实的过去）","options":["aurait été","était","serait","a été"],"answer":"aurait été","explain":"条件式过去时表未经证实的过去信息（「据报」）：aurait été reporté；était 和 a été 是直陈式（表已确认事实），serait 是条件式现在时，不能表达已完成的过去。","source":"语法点 · 条件式过去时（le conditionnel passé） · grammar-b1b2.html#cond-passe"},{"id":"q-gram-b2-0015","level":"B2","skill":"grammar","prompt":"___ il pleuvait, le match serait annulé.","options":["Au cas où","En cas de","À condition que","Sinon"],"answer":"Au cas où","explain":"au cas où + 未完成过去时（或条件式）可替代 si 表假设；en cas de 后接名词，à condition que 后接虚拟式，sinon 是「否则」并引出结果句。","source":"语法点 · si 的替代结构（les substituts de si） · grammar-b1b2.html#si-alternatives"},{"id":"q-gram-b2-0016","level":"B2","skill":"grammar","prompt":"___ de retard, prévenez-nous.","options":["En cas","Au cas où","À condition","Sinon"],"answer":"En cas","explain":"en cas de + 名词 = 「如果发生……」（en cas de retard）；au cas où 后接从句，à condition 必须配 que，sinon 是副词「否则」，不能接 de retard。","source":"语法点 · si 的替代结构（les substituts de si） · grammar-b1b2.html#si-alternatives"},{"id":"q-gram-b2-0017","level":"B2","skill":"grammar","prompt":"Dépêche-toi, ___ nous serons en retard.","options":["sinon","si","sinon que","à moins"],"answer":"sinon","explain":"sinon 表「否则」，引出否定的后果；si 表示条件而不表「否则」，sinon que 后接从句且意思是「除了」，à moins 必须配 que 且表「除非」。","source":"语法点 · si 的替代结构（les substituts de si） · grammar-b1b2.html#si-alternatives"},{"id":"q-gram-b2-0018","level":"B2","skill":"grammar","prompt":"Cet enfant est aimé ___ tous ses camarades.","options":["de","par","à","pour"],"answer":"de","explain":"表情感与心理状态的动词（aimer, respecter, estimer）用 de 引导施动者：aimé de tous；par 强调动作施动者，à 和 pour 不引导施动者。","source":"语法点 · 施动者 par 与 de（par ou de + agent） · grammar-b1b2.html#passif-par-de"},{"id":"q-gram-b2-0019","level":"B2","skill":"grammar","prompt":"La ville était entourée ___ collines.","options":["de","par","avec","à"],"answer":"de","explain":"表状态的被动态（entouré de, couvert de, bordé de）用 de；par 强调施动动作，avec 表伴随，à 不用于此结构。","source":"语法点 · 施动者 par 与 de（par ou de + agent） · grammar-b1b2.html#passif-par-de"},{"id":"q-gram-b2-0020","level":"B2","skill":"grammar","prompt":"Ce vin ___ frais.（se boire，表特性）","options":["se boit","est bu","boit","se boira"],"answer":"se boit","explain":"代动词被动表事物的常态特性：ce vin se boit frais（这种酒要冰着喝）；est bu 是被动态（强调动作而非特性），boit 缺自反代词，se boira 是将来时。","source":"语法点 · 代动词被动与 on（le passif pronominal） · grammar-b1b2.html#passif-pronominal"},{"id":"q-gram-b2-0021","level":"B2","skill":"grammar","prompt":"Dans ce magasin, on ___ des billets au guichet.","options":["vend","vends","vendez","est vendu"],"answer":"vend","explain":"on 后动词用第三人称单数 vend，这是比被动态更自然的无人称被动；vends 是 je / tu 形式，vendez 是 vous 形式，est vendu 与主语 des billets 不搭配。","source":"语法点 · 代动词被动与 on（le passif pronominal） · grammar-b1b2.html#passif-pronominal"},{"id":"q-gram-b2-0022","level":"B2","skill":"grammar","prompt":"Le professeur fait ___ les élèves.（travailler）","options":["travailler","travaillent","travaillé","de travailler"],"answer":"travailler","explain":"faire + 不定式表使役，不定式不变位：fait travailler les élèves；travaillent 变成变位动词，travaillé 是过去分词，de travailler 多了介词。","source":"语法点 · 使役结构（la construction causative） · grammar-b1b2.html#causatif"},{"id":"q-gram-b2-0023","level":"B2","skill":"grammar","prompt":"Elle a fait ___ sa voiture hier.（réparer）","options":["réparer","réparée","réparé","en réparant"],"answer":"réparer","explain":"faire + 不定式表使役，faire 的过去分词不配合、不定式也不变：a fait réparer sa voiture；réparée / réparé 是多余配合，en réparant 是副动词（表方式而非使役）。","source":"语法点 · 使役结构（la construction causative） · grammar-b1b2.html#causatif"},{"id":"q-gram-b2-0024","level":"B2","skill":"grammar","prompt":"Elle fait ___ ses enfants le matin.（se lever）","options":["se lever","lever","se lèvent","levé"],"answer":"se lever","explain":"faire + 代词式不定式时自反代词必须保留：fait se lever ses enfants；lever 丢了自反代词，se lèvent 把不定式变位了，levé 是过去分词。","source":"语法点 · 使役结构（la construction causative） · grammar-b1b2.html#causatif"},{"id":"q-gram-b2-0025","level":"B2","skill":"grammar","prompt":"Les étudiants ___ ce cours sont en B2.（suivre）","options":["suivant","suivants","suivi","suivent"],"answer":"suivant","explain":"现在分词有动词性、不变形，可替代 qui 从句：les étudiants suivant ce cours = qui suivent；suivants 是形容词形式（意为「下列的」），suivi 是过去分词，suivent 是变位动词，都不能这样作定语。","source":"语法点 · 现在分词（le participe présent） · grammar-b1b2.html#participe-present"},{"id":"q-gram-b2-0026","level":"B2","skill":"grammar","prompt":"___ qu'il était malade, il est resté chez lui.","options":["Étant","Est","Été","Être"],"answer":"Étant","explain":"现在分词表原因，且要与主句主语一致（il）：Étant malade…；Est 是变位动词，Été 是过去分词（需配助动词），Être 是原形。","source":"语法点 · 现在分词（le participe présent） · grammar-b1b2.html#participe-present"},{"id":"q-gram-b2-0027","level":"B2","skill":"grammar","prompt":"___ bien les consignes, elle a commencé l'exercice.","options":["Comprenant","Compris","Comprend","Comprendre"],"answer":"Comprenant","explain":"现在分词表原因，与主句主语 elle 一致：Comprenant bien les consignes…；Compris 是过去分词（若要表先时性需写 ayant compris），Comprend 是变位形式，Comprendre 是原形。","source":"语法点 · 现在分词（le participe présent） · grammar-b1b2.html#participe-present"},{"id":"q-gram-b2-0028","level":"B2","skill":"grammar","prompt":"Il écoute de la musique ___ ses devoirs.（faire）","options":["en faisant","en fait","faisant","en faire"],"answer":"en faisant","explain":"副动词＝en + 现在分词，表同时进行的动作：en faisant ses devoirs，且主语必须与主句一致；en fait 是副词短语「事实上」，faisant 缺 en，en faire 是原形。","source":"语法点 · 副动词（le gérondif） · grammar-b1b2.html#gerondif"},{"id":"q-gram-b2-0029","level":"B2","skill":"grammar","prompt":"___ , tu aurais réussi.（travailler plus）","options":["En travaillant plus","Travaillant plus","En travaillé plus","En travailler plus"],"answer":"En travaillant plus","explain":"副动词可表条件（＝si tu avais travaillé plus）：en + 现在分词；缺 en 就不是副动词，travaillé 是过去分词，travailler 是原形。","source":"语法点 · 副动词（le gérondif） · grammar-b1b2.html#gerondif"},{"id":"q-gram-b2-0030","level":"B2","skill":"grammar","prompt":"Elle a appris le français ___ des séries.（regarder）","options":["en regardant","regardant","en regardé","en regarder"],"answer":"en regardant","explain":"副动词表方式（通过做某事）：en regardant des séries；缺 en 变成普通分词，regardé 是过去分词不能构成副动词，regarder 是原形。","source":"语法点 · 副动词（le gérondif） · grammar-b1b2.html#gerondif"},{"id":"q-gram-b2-0031","level":"B2","skill":"grammar","prompt":"___ fini ses devoirs, il est sorti.","options":["Ayant","Étant","Avoir","En"],"answer":"Ayant","explain":"复合过去分词＝ayant / étant + 过去分词，表先时性：ayant fini（finir 用 avoir）；Étant 需配 être 型动词（étant parti），Avoir 是原形，En 引导副动词不能与过去分词连用。","source":"语法点 · 复合过去分词（le participe passé composé） · grammar-b1b2.html#participe-compose"},{"id":"q-gram-b2-0032","level":"B2","skill":"grammar","prompt":"___ arrivée en retard, elle n'a pas pu entrer.","options":["Étant","Ayant","Étant arrivé","En étant"],"answer":"Étant","explain":"arriver 用 être 作助动词，所以复合过去分词是 étant arrivée（与阴性主语配合）；Ayant 用于 avoir 型动词，Étant arrivé 缺配合，En étant 把副动词与复合分词混用。","source":"语法点 · 复合过去分词（le participe passé composé） · grammar-b1b2.html#participe-compose"},{"id":"q-gram-b2-0033","level":"B2","skill":"grammar","prompt":"Les élèves qui ont terminé l'exercice peuvent sortir. → Les élèves ___ l'exercice peuvent sortir.","options":["ayant terminé","terminant","terminés","en terminant"],"answer":"ayant terminé","explain":"从句动作先于主句，压缩为复合过去分词 ayant terminé；terminant 表同时，terminés 变成形容词性短语（语义改变），en terminant 是副动词（表方式或同时）。","source":"语法点 · 分词式与从句互转（la transformation participiale） · grammar-b1b2.html#participe-relative"},{"id":"q-gram-b2-0034","level":"B2","skill":"grammar","prompt":"Comme il était fatigué, il est allé se coucher. → ___ , il est allé se coucher.","options":["Étant fatigué","Été fatigué","En étant fatigué","Fatigué étant"],"answer":"Étant fatigué","explain":"原因从句可压缩为现在分词短语 étant fatigué（主语一致）；Été fatigué 缺助动词，en étant fatigué 更偏向方式或同时，Fatigué étant 语序不成立。","source":"语法点 · 分词式与从句互转（la transformation participiale） · grammar-b1b2.html#participe-relative"},{"id":"q-gram-b2-0035","level":"B2","skill":"grammar","prompt":"Le projet qui a été accepté hier est ambitieux. → Le projet ___ hier est ambitieux.","options":["accepté","acceptant","ayant accepté","en acceptant"],"answer":"accepté","explain":"被动的关系从句可压缩为过去分词短语 accepté（过去分词起形容词作用，与名词配合）；acceptant 是主动的现在分词，ayant accepté 表主动完成，en acceptant 是副动词。","source":"语法点 · 分词式与从句互转（la transformation participiale） · grammar-b1b2.html#participe-relative"},{"id":"q-gram-b2-0036","level":"B2","skill":"grammar","prompt":"Voici l'auteur ___ le roman a été traduit en chinois.","options":["dont","que","lequel","duquel"],"answer":"dont","explain":"dont 替代 de + 先行词，这里表所属关系（le roman de cet auteur）；que 只作直接宾语，lequel 必须紧跟介词，duquel 用于 de + lequel 的介词结构（如 près duquel）。","source":"语法点 · 关系代词 dont（le pronom relatif dont） · grammar-b1b2.html#rel-dont"},{"id":"q-gram-b2-0037","level":"B2","skill":"grammar","prompt":"C'est un problème ___ il faut tenir compte.","options":["dont","que","duquel","auquel"],"answer":"dont","explain":"tenir compte de qch 中的 de 由 dont 替代；que 丢掉了介词，duquel 要与介词连用（如 près duquel），auquel 对应 à + lequel。","source":"语法点 · 关系代词 dont（le pronom relatif dont） · grammar-b1b2.html#rel-dont"},{"id":"q-gram-b2-0038","level":"B2","skill":"grammar","prompt":"La maison ___ je rêve est au bord de la mer.（我梦想的房子）","options":["dont","que","où","laquelle"],"answer":"dont","explain":"rêver de qch 的 de 由 dont 替代；que 缺介词，où 表示「我在那里做梦」的地点关系，与「梦想拥有」的意思不符，laquelle 单独使用缺少介词。","source":"语法点 · 关系代词 dont（le pronom relatif dont） · grammar-b1b2.html#rel-dont"},{"id":"q-gram-b2-0039","level":"B2","skill":"grammar","prompt":"C'est le collègue avec ___ je travaille.","options":["lequel","laquelle","lesquels","dont"],"answer":"lequel","explain":"介词 + 关系代词指人时用 lequel（avec lequel，口语也说 avec qui）；先行词 le collègue 是阳性单数，所以 laquelle 性别错、lesquels 单复数错；dont 替代 de + 名词，不能跟在 avec 后。","source":"语法点 · 关系代词 lequel（le pronom relatif composé） · grammar-b1b2.html#rel-lequel"},{"id":"q-gram-b2-0040","level":"B2","skill":"grammar","prompt":"Les outils avec ___ il travaille sont neufs.","options":["lesquels","lesquelles","que","dont"],"answer":"lesquels","explain":"先行词 outils 是阳性复数，介词 avec 后用 lesquels；lesquelles 是阴性复数，que 不能跟在介词后，dont 替代 de + 名词。","source":"语法点 · 关系代词 lequel（le pronom relatif composé） · grammar-b1b2.html#rel-lequel"},{"id":"q-gram-b2-0041","level":"B2","skill":"grammar","prompt":"La personne ___ j'ai parlé est la directrice.（我跟她说过话）","options":["à qui","auquel","lesquelles","dont"],"answer":"à qui","explain":"先行词是「人」（la personne，阴性单数），parler à qqn 用 à qui（书面也可说 à laquelle）；auquel 是阳性缩合形式，lesquelles 是复数，dont 会变成 parler de（我谈到的人），与「跟她说话」这个意思不符。","source":"语法点 · 关系代词 lequel（le pronom relatif composé） · grammar-b1b2.html#rel-lequel"},{"id":"q-gram-b2-0042","level":"B2","skill":"grammar","prompt":"___ m'intéresse, c'est la culture française.","options":["Ce qui","Ce que","Ce dont","Ce à quoi"],"answer":"Ce qui","explain":"无先行词的关系代词在从句中作主语用 ce qui；ce que 作直接宾语，ce dont 替代 de + 事物，ce à quoi 替代 à + 事物。","source":"语法点 · ce qui / ce que / ce dont（les pronoms relatifs indéfinis） · grammar-b1b2.html#rel-ce-qui"},{"id":"q-gram-b2-0043","level":"B2","skill":"grammar","prompt":"Je ne comprends pas ___ tu dis.","options":["ce que","ce qui","ce dont","ce à quoi"],"answer":"ce que","explain":"从句中 dire 缺直接宾语，用 ce que；ce qui 作主语，ce dont 替代 de + 事物，ce à quoi 替代 à + 事物。","source":"语法点 · ce qui / ce que / ce dont（les pronoms relatifs indéfinis） · grammar-b1b2.html#rel-ce-qui"},{"id":"q-gram-b2-0044","level":"B2","skill":"grammar","prompt":"Voilà ___ j'ai besoin.","options":["ce dont","ce que","ce qui","ce à quoi"],"answer":"ce dont","explain":"avoir besoin de qch 的 de 由 ce dont 替代；ce que 缺介词，ce qui 作主语，ce à quoi 对应 à + 事物。","source":"语法点 · ce qui / ce que / ce dont（les pronoms relatifs indéfinis） · grammar-b1b2.html#rel-ce-qui"},{"id":"q-gram-b2-0045","level":"B2","skill":"grammar","prompt":"C'est une conférence ___ j'ai assisté.","options":["à laquelle","à qui","dont","que"],"answer":"à laquelle","explain":"assister à qch 用介词 à + 关系代词，先行词 conférence 是阴性单数，所以是 à laquelle；à qui 只用于指人，dont 替代 de + 名词，que 不能跟在介词后。","source":"语法点 · 复合关系代词（d'où / grâce auquel） · grammar-b1b2.html#rel-compose"},{"id":"q-gram-b2-0046","level":"B2","skill":"grammar","prompt":"C'est le professeur grâce ___ j'ai réussi.","options":["auquel","duquel","dont","que"],"answer":"auquel","explain":"grâce à + 阳性单数先行词 → grâce auquel；duquel 对应 de + lequel，dont 替代 de 而不是 grâce à，que 不能跟在介词后。","source":"语法点 · 复合关系代词（d'où / grâce auquel） · grammar-b1b2.html#rel-compose"},{"id":"q-gram-b2-0047","level":"B2","skill":"grammar","prompt":"Il a beaucoup d'expérience, ___ il est encore jeune.","options":["cependant","parce que","donc","car"],"answer":"cependant","explain":"前后是对立关系，用 cependant（然而）；parce que 和 car 表原因，donc 表结果。","source":"语法点 · 对立与转折连接（l'opposition） · grammar-b1b2.html#conn-opposition"},{"id":"q-gram-b2-0048","level":"B2","skill":"grammar","prompt":"La situation est difficile ; ___ , elle n'est pas désespérée.","options":["en revanche","par conséquent","en effet","de plus"],"answer":"en revanche","explain":"en revanche 表对比转折（「相反地」）；par conséquent 表结果，en effet 表解释或证实，de plus 表递进。","source":"语法点 · 对立与转折连接（l'opposition） · grammar-b1b2.html#conn-opposition"},{"id":"q-gram-b2-0049","level":"B2","skill":"grammar","prompt":"___ les prix baissent, la demande reste faible.","options":["Alors qu'","Parce qu'","Dès qu'","Afin qu'"],"answer":"Alors qu'","explain":"alors que 表对立（「然而」）；parce que 表原因，dès que 表时间，afin que 表目的且需虚拟式。","source":"语法点 · 对立与转折连接（l'opposition） · grammar-b1b2.html#conn-opposition"},{"id":"q-gram-b2-0050","level":"B2","skill":"grammar","prompt":"___ il soit tard, il continue à travailler.","options":["Bien qu'","Même si","Malgré","Pourtant"],"answer":"Bien qu'","explain":"bien que 后接虚拟式（soit）；même si 后接直陈式，malgré 后接名词，pourtant 是副词，不能引导从句。","source":"语法点 · 让步连接（la concession） · grammar-b1b2.html#conn-concession"},{"id":"q-gram-b2-0051","level":"B2","skill":"grammar","prompt":"___ il est tard, il continue à travailler.","options":["Même si","Bien qu'","Malgré","Quoique"],"answer":"Même si","explain":"même si 后接直陈式 est；bien que 和 quoique 后必须接虚拟式（soit），malgré 后接名词。","source":"语法点 · 让步连接（la concession） · grammar-b1b2.html#conn-concession"},{"id":"q-gram-b2-0052","level":"B2","skill":"grammar","prompt":"___ la pluie, nous sommes sortis.","options":["Malgré","Bien que","Même si","Quoique"],"answer":"Malgré","explain":"malgré 是介词，后接名词（malgré la pluie）；bien que、quoique、même si 都要求接从句。","source":"语法点 · 让步连接（la concession） · grammar-b1b2.html#conn-concession"},{"id":"q-gram-b2-0053","level":"B2","skill":"grammar","prompt":"Les prix ont augmenté. → ___ des prix a inquiété les consommateurs.","options":["L'augmentation","L'augmentement","L'augmenter","Augmenter"],"answer":"L'augmentation","explain":"augmenter 的名词化是 l'augmentation（-ation 后缀）；augmentement 是生造词（把英语式 -ment 套错），augmenter 是动词原形，不能作主语中心词。","source":"语法点 · 动词名词化（la nominalisation des verbes） · grammar-b1b2.html#nom-verbes"},{"id":"q-gram-b2-0054","level":"B2","skill":"grammar","prompt":"Le gouvernement a décidé de réformer. → La ___ de réformer a été annoncée.","options":["décision","décidément","décider","décide"],"answer":"décision","explain":"décider 的名词化是 la décision；décidément 是副词「确实」，décider 是原形，décide 是变位动词，都不能作名词。","source":"语法点 · 动词名词化（la nominalisation des verbes） · grammar-b1b2.html#nom-verbes"},{"id":"q-gram-b2-0055","level":"B2","skill":"grammar","prompt":"Ils ont construit un nouveau pont. → La ___ d'un nouveau pont a pris deux ans.","options":["construction","construisement","construire","construit"],"answer":"construction","explain":"construire 的名词化是 la construction；construisement 是生造词，construire 是原形，construit 是过去分词。","source":"语法点 · 动词名词化（la nominalisation des verbes） · grammar-b1b2.html#nom-verbes"},{"id":"q-gram-b2-0056","level":"B2","skill":"grammar","prompt":"Il est heureux. → Son ___ se voit tout de suite.","options":["bonheur","heureuseté","heureux","heureusement"],"answer":"bonheur","explain":"heureux 的名词化是不规则的 le bonheur；heureuseté 是生造词，heureux 是形容词不能作主语中心词，heureusement 是副词。","source":"语法点 · 形容词名词化（la nominalisation des adjectifs） · grammar-b1b2.html#nom-adj"},{"id":"q-gram-b2-0057","level":"B2","skill":"grammar","prompt":"Elle est généreuse. → Sa ___ est connue de tous.","options":["générosité","généreuseté","généreuse","généreusement"],"answer":"générosité","explain":"généreux 的名词化是 la générosité（-ité 后缀）；généreuseté 是生造词，généreuse 是形容词，généreusement 是副词。","source":"语法点 · 形容词名词化（la nominalisation des adjectifs） · grammar-b1b2.html#nom-adj"},{"id":"q-gram-b2-0058","level":"B2","skill":"grammar","prompt":"On constate que les jeunes lisent moins. 最符合书面语体的改写是：","options":["Une baisse de la lecture chez les jeunes est constatée.","On voit que les jeunes lisent moins bien.","Les jeunes ne lisent pas.","Il faut que les jeunes lisent."],"answer":"Une baisse de la lecture chez les jeunes est constatée.","explain":"书面语体靠名词化（une baisse de la lecture）加无人称被动（est constatée）来压缩信息；第二项仍是口语式主谓结构，第三项丢失比较信息且过于绝对，第四项改变了原意变成呼吁。","source":"语法点 · 书面语体特征（le style écrit） · grammar-b1b2.html#nom-style"},{"id":"q-gram-b2-0059","level":"B2","skill":"grammar","prompt":"Les prix montent, donc les gens consomment moins. 最符合书面语体的改写是：","options":["La hausse des prix entraîne une baisse de la consommation.","Les prix montent et les gens consomment moins.","Les prix, les gens et la consommation.","Il faut baisser les prix."],"answer":"La hausse des prix entraîne une baisse de la consommation.","explain":"书面语要求逻辑显性化（entraîner 替代 donc）加名词化（la hausse / une baisse）；第二项保留口语连接，第三项信息残缺，第四项改变了论述方向。","source":"语法点 · 书面语体特征（le style écrit） · grammar-b1b2.html#nom-style"},{"id":"q-gram-b2-0060","level":"B2","skill":"grammar","prompt":"___ compte, c'est la régularité.","options":["Ce qui","Ce que","Ce dont","Ce à quoi"],"answer":"Ce qui","explain":"间接强调结构 ce qui…c'est 中，被强调部分在从句里作主语：ce qui compte, c'est…；ce que 作宾语，ce dont 替代 de + 事物，ce à quoi 替代 à + 事物。","source":"语法点 · ce qui / ce que … c'est（la mise en relief indirecte） · grammar-b1b2.html#mer-cequi-cest"},{"id":"q-gram-b2-0061","level":"B2","skill":"grammar","prompt":"___ je veux, c'est un travail intéressant.","options":["Ce que","Ce qui","Ce dont","Ce à quoi"],"answer":"Ce que","explain":"从句中 vouloir 缺直接宾语，用 ce que；ce qui 作主语，ce dont 替代 de + 事物，ce à quoi 替代 à + 事物。","source":"语法点 · ce qui / ce que … c'est（la mise en relief indirecte） · grammar-b1b2.html#mer-cequi-cest"},{"id":"q-gram-b2-0062","level":"B2","skill":"grammar","prompt":"Il ne pense ___ à son travail.","options":["qu'","que","pas","rien"],"answer":"qu'","explain":"ne…que 表限制「只、仅仅」，不是否定：il ne pense qu'à son travail；只写 pas 变成否定，rien 表「什么也不」，que 在元音前必须省音为 qu'。","source":"语法点 · 其他强调手段与倒装（les autres procédés d'insistance） · grammar-b1b2.html#mer-autres"},{"id":"q-gram-b2-0063","level":"B2","skill":"grammar","prompt":"C'est ___ il est en retard : il a raté son train.","options":["qu'","que","ce qui","ce que"],"answer":"qu'","explain":"c'est que 引出解释（「原因是……」），que 在元音 il 前省音为 qu'；不省音的 que 是拼写错误，ce qui / ce que 不能构成这个固定结构。","source":"语法点 · 其他强调手段与倒装（les autres procédés d'insistance） · grammar-b1b2.html#mer-autres"},{"id":"q-gram-b2-0064","level":"B2","skill":"grammar","prompt":"___ fatigué qu'il soit, il ne renonce jamais.","options":["Si","Tant","Très","Tellement"],"answer":"Si","explain":"si + 形容词 + que + 虚拟式表让步（「无论多么累」）：si fatigué qu'il soit；tant 修饰动词或名词，très 不能构成这个结构，tellement 用于结果从句（tellement…que + 直陈式）。","source":"语法点 · 其他强调手段与倒装（les autres procédés d'insistance） · grammar-b1b2.html#mer-autres"},{"id":"q-gram-b2-0065","level":"B2","skill":"grammar","prompt":"Jamais je ___ vu un tel spectacle.","options":["n'ai","ai","n'aurai","n'aie"],"answer":"n'ai","explain":"jamais 提到句首构成强调，但仍保留 ne：jamais je n'ai vu…；单独 ai 缺 ne，n'aurai 是将来时，n'aie 是虚拟式（这里是陈述事实）。","source":"语法点 · 其他强调手段与倒装（les autres procédés d'insistance） · grammar-b1b2.html#mer-autres"},{"id":"q-gram-b2-0066","level":"B2","skill":"grammar","prompt":"Je m'intéresse ___ la peinture.","options":["à","dans","de","pour"],"answer":"à","explain":"s'intéresser à qch 是固定搭配，用 à；dans 是受中文「对……感兴趣」联想影响最常见的误搭，de 和 pour 也不合这个动词的搭配。","source":"语法点 · 动词 + 介词搭配（les verbes et leurs prépositions） · grammar-b1b2.html#verbes-prepositions"},{"id":"q-gram-b2-0067","level":"B2","skill":"grammar","prompt":"Il dépend ___ ses parents pour ses études.","options":["de","à","sur","avec"],"answer":"de","explain":"dépendre de qqn / qch 用 de；à 是常见误搭，sur 受英语 depend on 影响，avec 表伴随。","source":"语法点 · 动词 + 介词搭配（les verbes et leurs prépositions） · grammar-b1b2.html#verbes-prepositions"},{"id":"q-gram-b2-0068","level":"B2","skill":"grammar","prompt":"Elle tient beaucoup ___ cette photo de famille.","options":["à","de","pour","sur"],"answer":"à","explain":"tenir à qch 意为「珍视、看重」，用 à；tenir de qqn 是「长得像某人」，tenir pour 是「认为」，sur 不搭配。","source":"语法点 · 动词 + 介词搭配（les verbes et leurs prépositions） · grammar-b1b2.html#verbes-prepositions"},{"id":"q-gram-b2-0069","level":"B2","skill":"grammar","prompt":"Nous manquons ___ temps cette semaine.","options":["de","à","pour","dans"],"answer":"de","explain":"manquer de qch 意为「缺少某物」，用 de；manquer à qqn 是「（某人）缺席或辜负某人」，pour 和 dans 不搭配。","source":"语法点 · 动词 + 介词搭配（les verbes et leurs prépositions） · grammar-b1b2.html#verbes-prepositions"},{"id":"q-gram-b2-0070","level":"B2","skill":"grammar","prompt":"Il s'est excusé ___ son retard.","options":["de","pour","à","sur"],"answer":"de","explain":"s'excuser de qch 意为「为某事道歉」，用 de；pour 是英语式误搭（excuse me for），à 和 sur 不搭配。","source":"语法点 · 动词 + 介词搭配（les verbes et leurs prépositions） · grammar-b1b2.html#verbes-prepositions"},{"id":"q-gram-b2-0071","level":"B2","skill":"grammar","prompt":"___ est de constater que les résultats sont décevants.","options":["Force","Il faut","On doit","C'est"],"answer":"Force","explain":"书面固定结构 force est de constater que ＝「不得不承认」；il faut que 后要接虚拟式，on doit 后接不定式不能直接接 est，c'est 不能构成这个惯用结构。","source":"语法点 · B2 高频固定搭配（les expressions du niveau B2） · grammar-b1b2.html#expressions-b2"},{"id":"q-gram-b2-0072","level":"B2","skill":"grammar","prompt":"___ , il faut agir vite.","options":["En tout état de cause","En tout cas de cause","Tout état","À tout état"],"answer":"En tout état de cause","explain":"惯用结构 en tout état de cause ＝「无论如何」；其余三项是搭配和拼写错误的生造形式。","source":"语法点 · B2 高频固定搭配（les expressions du niveau B2） · grammar-b1b2.html#expressions-b2"},{"id":"q-gram-b2-0073","level":"B2","skill":"grammar","prompt":"Ce phénomène ___ une attention particulière.","options":["mérite","mérite de","vaut","mérite pour"],"answer":"mérite","explain":"mériter 直接接名词宾语：mériter une attention particulière；mériter de 后接不定式（mériter d'être étudié），vaut 需搭配名词且语义为「值」，mérite pour 搭配错误。","source":"语法点 · B2 高频固定搭配（les expressions du niveau B2） · grammar-b1b2.html#expressions-b2"},{"id":"q-gram-b2-0074","level":"B2","skill":"grammar","prompt":"___ dire que la situation s'améliore nettement.","options":["C'est","Il est","Ce sont","Elle est"],"answer":"C'est","explain":"c'est dire que ＝「也就是说」是书面固定表达；il est 后需接形容词或 que 从句结构，ce sont 是复数，elle est 主谓不一致。","source":"语法点 · B2 高频固定搭配（les expressions du niveau B2） · grammar-b1b2.html#expressions-b2"}],"listening":[{"id":"q-listen-b2-0001","level":"B2","skill":"listening","prompt":"[听力原文] Force est de constater que la réforme n'a pas produit les effets escomptés, faute de moyens suffisants. 问题：Pourquoi la réforme n'a-t-elle pas eu les effets attendus ?","options":["Par manque de moyens","Par manque de volonté politique","À cause de l'opposition des syndicats","Parce qu'elle a été mal rédigée"],"answer":"Par manque de moyens","explain":"faute de moyens suffisants ＝「由于缺乏足够手段」，是明确原因；政治意愿、工会反对、文本质量都没有出现在原话里。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0002","level":"B2","skill":"listening","prompt":"[听力原文] Si les États avaient signé l'accord plus tôt, nous n'en serions pas là aujourd'hui. 问题：Que suggère le locuteur ?","options":["Un retard dans la signature a aggravé la situation","L'accord a été signé trop tôt","L'accord n'a aucune importance","Les États ont refusé tout accord"],"answer":"Un retard dans la signature a aggravé la situation","explain":"si + 愈过去时（avaient signé）配主句条件式现在时（n'en serions pas là）表与事实相反的假设，即「当年签得太晚」；其余选项曲解了假设结构。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0003","level":"B2","skill":"listening","prompt":"[听力原文] L'étude révèle une corrélation entre le niveau de diplôme et la durée d'accès à l'emploi, sans pour autant établir de lien de causalité. 问题：Que précise l'étude ?","options":["Une corrélation, mais pas de causalité","Une relation de cause à effet","Aucune relation","Une baisse du chômage"],"answer":"Une corrélation, mais pas de causalité","explain":"sans pour autant établir de lien de causalité 明确否定因果结论；其余选项把关联夸大成因果，或否定任何联系。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0004","level":"B2","skill":"listening","prompt":"[听力原文] Je ne nie pas que ces mesures soient nécessaires ; je conteste en revanche la manière dont elles sont appliquées. 问题：Que conteste le locuteur ?","options":["La manière d'appliquer les mesures","La nécessité des mesures","L'utilité de toute réforme","Le coût des mesures"],"answer":"La manière d'appliquer les mesures","explain":"分号后的 en revanche 才是重点：la manière dont elles sont appliquées；nécessaire 已被 je ne nie pas 承认，成本与整体否定都超出原话。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0005","level":"B2","skill":"listening","prompt":"[听力原文] La direction a annoncé la suppression de deux cents postes, ce qui a provoqué un mouvement de grève immédiat. 问题：Quelle a été la conséquence de cette annonce ?","options":["Un mouvement de grève","Une hausse des salaires","La création de postes","Une réunion de négociation"],"answer":"Un mouvement de grève","explain":"ce qui a provoqué 引出后果：grève immédiate；création de postes 与 suppression 相反，其他选项都没有出现。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0006","level":"B2","skill":"listening","prompt":"[听力原文] Il aurait fallu agir dès le premier signalement ; aujourd'hui, le problème est devenu difficile à maîtriser. 问题：Que reproche-t-on ?","options":["Un manque de réactivité","Un excès de prudence","Un manque de budget seulement","Une erreur de diagnostic initial"],"answer":"Un manque de réactivité","explain":"il aurait fallu agir dès le premier signalement 表责备「本该第一时间就行动」，即缺乏及时反应；预算和诊断都不是原话要点。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0007","level":"B2","skill":"listening","prompt":"[听力原文] Bien que le dispositif ait été présenté comme provisoire, il pourrait être reconduit pour trois ans. 问题：Que dit-on du dispositif ?","options":["Il est provisoire en principe, mais pourrait durer","Il est définitif depuis trois ans","Il a été supprimé","Il ne sera jamais reconduit"],"answer":"Il est provisoire en principe, mais pourrait durer","explain":"bien que… ait été présenté comme provisoire 表示「名义上只是临时」，主句 il pourrait être reconduit pour trois ans 表可能延长，两项要合起来理解。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0008","level":"B2","skill":"listening","prompt":"[听力原文] Le rapport souligne que la baisse de la consommation s'explique moins par une perte de pouvoir d'achat que par un changement des habitudes. 问题：Selon le rapport, quelle est la cause principale ?","options":["Un changement des habitudes","Une perte de pouvoir d'achat","Une hausse des impôts","Une baisse de la population"],"answer":"Un changement des habitudes","explain":"moins… que… 结构中 que 之后才是主因：changement des habitudes；购买力下降是次要项，税收和人口都没有提到。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0009","level":"B2","skill":"listening","prompt":"[听力原文] — Pensez-vous que cette politique puisse réduire les inégalités ? — Je crains que les effets ne soient limités à court terme. 问题：Quelle est la réponse de l'expert ?","options":["Il craint que les effets soient limités","Il est certain que la politique échouera","Il pense que les effets seront immédiats","Il refuse de répondre"],"answer":"Il craint que les effets soient limités","explain":"je crains que + 虚拟式（ne soient，ne 是赘词）表担心效果有限；「一定失败」和「立刻见效」都超出了原话。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0010","level":"B2","skill":"listening","prompt":"[听力原文] Non seulement le texte a été adopté à une large majorité, mais il a aussi été salué par l'opposition. 问题：Que dit-on du texte ?","options":["Il a été adopté et bien accueilli par l'opposition","Il a été rejeté","Il a été adopté de justesse","Il a été retiré avant le vote"],"answer":"Il a été adopté et bien accueilli par l'opposition","explain":"non seulement… mais aussi… 表双重肯定：以较大优势通过，并获得反对派称赞；rejeté、de justesse、retiré 都与原话矛盾。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0011","level":"B2","skill":"listening","prompt":"[听力原文] À supposer que le financement soit obtenu, le chantier ne pourrait pas démarrer avant le printemps. 问题：Quelle est la condition et quel est le délai ?","options":["Il faut d'abord le financement, et le chantier ne démarrera pas avant le printemps","Le chantier démarre immédiatement","Le financement est déjà assuré","Le projet est abandonné"],"answer":"Il faut d'abord le financement, et le chantier ne démarrera pas avant le printemps","explain":"à supposer que + 虚拟式（soit）表假设条件，主句条件式 pourrait 表保留；其他选项忽略了条件或时间限制，或把项目说成已放弃。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0012","level":"B2","skill":"listening","prompt":"[听力原文] Le médiateur a été saisi par une centaine de locataires, qui dénoncent des charges locatives excessives. 问题：Que dénoncent les locataires ?","options":["Des charges locatives excessives","Des loyers trop bas","L'absence de chauffage","La vétusté de l'immeuble"],"answer":"Des charges locatives excessives","explain":"关系从句 qui dénoncent… 是信息重点：charges locatives excessives；loyers trop bas 与原意相反，chauffage 和 vétusté 没有出现。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0013","level":"B2","skill":"listening","prompt":"[听力原文] En dépit de résultats encourageants, la direction reste prudente quant à l'objectif annoncé. 问题：Quelle est l'attitude de la direction ?","options":["Prudente malgré de bons résultats","Triomphante","Indifférente","Hostile au projet"],"answer":"Prudente malgré de bons résultats","explain":"en dépit de（＝malgré）引导让步，résultats encourageants 与 reste prudente 并存；凯旋、冷漠、敌意都与 prudente 不符。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0014","level":"B2","skill":"listening","prompt":"[听力原文] Si l'on en croit les derniers chiffres, la reprise serait plus fragile que prévu. 问题：Que suggèrent les derniers chiffres ?","options":["Une reprise plus fragile que prévu","Une reprise solide","Une récession confirmée","Une croissance record"],"answer":"Une reprise plus fragile que prévu","explain":"si l'on en croit（据……所说）加条件式 serait 表未经完全确认的判断：reprise plus fragile que prévu；record、solide、récession 都超出原话。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0015","level":"B2","skill":"listening","prompt":"[听力原文] L'auteur montre comment la numérisation, loin de supprimer les emplois, en transforme le contenu. 问题：Selon l'auteur, quel est l'effet de la numérisation ?","options":["Elle transforme le contenu des emplois","Elle supprime tous les emplois","Elle n'a aucun effet","Elle crée uniquement des emplois précaires"],"answer":"Elle transforme le contenu des emplois","explain":"loin de supprimer… 是否定前提（不是消灭工作），主句 en transforme le contenu 是结论；其余选项夸大或否定这一效应。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0016","level":"B2","skill":"listening","prompt":"[听力原文] Le comité recommande que les données soient anonymisées avant toute utilisation à des fins de recherche. 问题：Que recommande le comité ?","options":["Anonymiser les données avant de les utiliser","Interdire toute recherche","Vendre les données","Publier les données brutes"],"answer":"Anonymiser les données avant de les utiliser","explain":"recommander que + 虚拟式（soient anonymisées），条件语 avant toute utilisation 也不能丢；禁止研究、出售、公布原始数据都与建议相反。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0017","level":"B2","skill":"listening","prompt":"[听力原文] Faute d'accord entre les partenaires sociaux, les négociations ont été reportées à une date ultérieure. 问题：Pourquoi les négociations ont-elles été reportées ?","options":["Par absence d'accord","Parce qu'elles sont terminées","Par manque de participants","Parce que la loi l'interdit"],"answer":"Par absence d'accord","explain":"faute d'accord ＝「由于没有达成一致」；谈判已结束、缺参与者、法律禁止都与原话无关。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"},{"id":"q-listen-b2-0018","level":"B2","skill":"listening","prompt":"[听力原文] Ce n'est pas tant le montant de l'amende qui pose problème que son caractère automatique. 问题：Qu'est-ce qui pose problème ?","options":["Le caractère automatique de l'amende","Le montant de l'amende","L'absence d'amende","La lenteur de la procédure"],"answer":"Le caractère automatique de l'amende","explain":"ne pas tant… que… 结构把重点放在 que 之后：son caractère automatique；金额只是被弱化的次要项，其余选项没有依据。","source":"听力 · B2 报告与访谈（compréhension orale B2 · DELF）"}],"reading":[{"id":"q-read-b2-0001","level":"B2","skill":"reading","prompt":"[阅读] La baisse de la consommation observée depuis deux ans s'explique moins par une perte de pouvoir d'achat que par une transformation des modes de vie. 问题：Selon le texte, quelle est la cause principale ?","options":["Une transformation des modes de vie","Une perte de pouvoir d'achat","Une hausse du chômage","Une baisse de la population"],"answer":"Une transformation des modes de vie","explain":"moins… que… 结构中 que 之后才是主要原因；购买力是次要项，失业率与人口都没有提到。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0002","level":"B2","skill":"reading","prompt":"[阅读] Force est de constater que les dispositifs d'aide existants, faute d'être évalués régulièrement, produisent des effets inégaux selon les territoires. 问题：Que reproche l'auteur aux dispositifs d'aide ?","options":["De ne pas être évalués régulièrement","D'être trop nombreux","De coûter trop cher","D'être réservés aux villes"],"answer":"De ne pas être évalués régulièrement","explain":"faute d'être évalués régulièrement ＝「因为缺乏定期评估」，这正是问题所在；数量、成本、地域限制都不是原文重点。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0003","level":"B2","skill":"reading","prompt":"[阅读] Loin de se réduire, l'écart entre les grandes métropoles et les villes moyennes s'est creusé au cours de la dernière décennie. 问题：Que dit le texte de l'écart entre métropoles et villes moyennes ?","options":["Il s'est creusé","Il s'est réduit","Il est resté stable","Il a disparu"],"answer":"Il s'est creusé","explain":"loin de se réduire（不仅没有缩小）后接主句 s'est creusé（反而扩大）；réduit 是被否定的前提，其余与原文矛盾。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0004","level":"B2","skill":"reading","prompt":"[阅读] Les auteurs soulignent que la numérisation, loin de supprimer des emplois, en transforme le contenu et exige de nouvelles compétences. 问题：Quel est l'effet de la numérisation selon les auteurs ?","options":["Elle transforme le contenu des emplois","Elle supprime des emplois","Elle n'a aucun effet","Elle réduit les compétences requises"],"answer":"Elle transforme le contenu des emplois","explain":"loin de supprimer 是否定前提，主句 en transforme le contenu 是结论；「减少所需技能」与 exige de nouvelles compétences 相反。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0005","level":"B2","skill":"reading","prompt":"[阅读] Si l'on en croit les projections disponibles, la demande d'énergie devrait diminuer, à condition que les politiques publiques restent ambitieuses. 问题：À quelle condition la demande d'énergie pourrait-elle diminuer ?","options":["Si les politiques publiques restent ambitieuses","Si les prix augmentent","Si la population baisse","Si les entreprises déménagent"],"answer":"Si les politiques publiques restent ambitieuses","explain":"à condition que 引出唯一条件；价格、人口、企业迁移都不是条件内容。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0006","level":"B2","skill":"reading","prompt":"[阅读] Le rapport, dont la publication était attendue depuis des mois, ne tranche pas la question de la responsabilité des autorités. 问题：Que dit-on du rapport ?","options":["Il ne tranche pas la question des responsabilités","Il condamne les autorités","Il a été publié immédiatement","Il a été retiré"],"answer":"Il ne tranche pas la question des responsabilités","explain":"dont 引导的关系从句只补充「被期待数月」，主句谓语 ne tranche pas 才是关键：没有裁定责任；「谴责当局」与原文相反。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0007","level":"B2","skill":"reading","prompt":"[阅读] Non seulement la mesure n'a pas permis de réduire les inégalités, mais elle a contribué à les aggraver dans certains secteurs. 问题：Quel est le bilan de cette mesure ?","options":["Elle n'a pas réduit les inégalités et les a parfois aggravées","Elle a réduit les inégalités","Elle a été sans effet","Elle a été supprimée"],"answer":"Elle n'a pas réduit les inégalités et les a parfois aggravées","explain":"non seulement… mais… 表递进的双重否定评价；「减少了不平等」与原文相反，「毫无效果」弱化了 aggraver。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0008","level":"B2","skill":"reading","prompt":"[阅读] Les experts recommandent que les données soient anonymisées avant toute utilisation à des fins commerciales. 问题：Que recommandent les experts ?","options":["Anonymiser les données avant un usage commercial","Interdire tout usage commercial","Vendre les données","Publier les données brutes"],"answer":"Anonymiser les données avant un usage commercial","explain":"recommander que + 虚拟式（soient anonymisées），并限定 avant tout usage commercial；禁止、出售、公布原始数据都超出建议范围。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0009","level":"B2","skill":"reading","prompt":"[阅读] Certes, la réforme a permis de simplifier certaines démarches ; elle reste toutefois difficile à appliquer pour les petites structures. 问题：Quelle est la position de l'auteur ?","options":["La réforme simplifie, mais reste difficile à appliquer","La réforme est un échec total","La réforme est parfaite","La réforme n'a rien changé"],"answer":"La réforme simplifie, mais reste difficile à appliquer","explain":"certes… toutefois… 是「固然……然而……」的让步结构，两方面都要保留；「彻底失败」「完美」都是片面解读。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0010","level":"B2","skill":"reading","prompt":"[阅读] Le dispositif, présenté comme provisoire lors de sa création, a été reconduit chaque année depuis dix ans. 问题：Que dit le texte de ce dispositif ?","options":["Prévu comme provisoire, il dure depuis dix ans","Il a été supprimé après un an","Il était définitif dès le départ","Il n'a jamais été renouvelé"],"answer":"Prévu comme provisoire, il dure depuis dix ans","explain":"分词短语 présenté comme provisoire 与 a été reconduit chaque année depuis dix ans 形成对比；其余选项与原文事实相反。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0011","level":"B2","skill":"reading","prompt":"[阅读] Ce n'est pas tant le coût du projet qui inquiète les riverains que l'absence de concertation. 问题：Qu'est-ce qui inquiète les riverains ?","options":["L'absence de concertation","Le coût du projet","La durée des travaux","La qualité des matériaux"],"answer":"L'absence de concertation","explain":"ne pas tant… que… 把重点放在 que 之后：缺乏协商；成本只是被弱化的次要因素，其他选项没有依据。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0012","level":"B2","skill":"reading","prompt":"[阅读] À supposer que le financement soit obtenu, le chantier ne pourrait pas démarrer avant le printemps, le temps d'obtenir les autorisations. 问题：Que faut-il comprendre ?","options":["Le financement est une condition et le démarrage dépend des autorisations","Le chantier démarre immédiatement","Le financement est déjà obtenu","Le projet est abandonné"],"answer":"Le financement est une condition et le démarrage dépend des autorisations","explain":"à supposer que + 虚拟式表假设条件，主句条件式加 le temps d'obtenir les autorisations 表延迟原因。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0013","level":"B2","skill":"reading","prompt":"[阅读] La corrélation entre niveau de diplôme et accès à l'emploi est bien établie ; en revanche, aucun lien de causalité n'a été démontré. 问题：Que précise l'article ?","options":["La corrélation est établie, mais la causalité n'est pas démontrée","Le diplôme cause directement l'accès à l'emploi","Il n'existe aucune corrélation","La causalité est prouvée"],"answer":"La corrélation est établie, mais la causalité n'est pas démontrée","explain":"en revanche 后面的信息要单独抓：没有证明因果关系；「因果已被证实」「毫无关联」都曲解了句子。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0014","level":"B2","skill":"reading","prompt":"[阅读] Les mesures annoncées, bien qu'elles aient été jugées insuffisantes par les associations, marquent une avancée sur le plan juridique. 问题：Quel jugement le texte porte-t-il sur ces mesures ?","options":["Insuffisantes mais juridiquement importantes","Totalement inutiles","Entièrement satisfaisantes","Contraires au droit"],"answer":"Insuffisantes mais juridiquement importantes","explain":"bien que + 虚拟式（aient été jugées insuffisantes）是让步，主句 marquent une avancée sur le plan juridique 是肯定；两个层面要同时保留。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0015","level":"B2","skill":"reading","prompt":"[阅读] La question n'est pas de savoir si le télétravail est souhaitable, mais comment en encadrer la pratique. 问题：Quelle est la question posée par l'auteur ?","options":["Comment encadrer le télétravail","Faut-il supprimer le télétravail","Le télétravail est-il souhaitable","Qui doit télétravailler"],"answer":"Comment encadrer le télétravail","explain":"la question n'est pas… mais… 把重点放在 mais 之后：如何规范实施；「是否可取」正是被作者搁置的问题。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0016","level":"B2","skill":"reading","prompt":"[阅读] Le texte prévoit que les entreprises de plus de cinquante salariés devront publier un rapport annuel, sous peine de sanctions financières. 问题：Que doivent faire les entreprises de plus de cinquante salariés ?","options":["Publier un rapport annuel","Réduire leurs effectifs","Augmenter les salaires","Fermer un site"],"answer":"Publier un rapport annuel","explain":"prévoir que 后是义务内容，sous peine de sanctions 表违约后果；裁员、加薪、关厂都不是要求。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0017","level":"B2","skill":"reading","prompt":"[阅读] Cette enquête, menée auprès de deux mille personnes, montre que la confiance dans les institutions varie fortement selon l'âge et le niveau de revenu. 问题：Que montre cette enquête ?","options":["La confiance varie selon l'âge et le revenu","La confiance est identique pour tous","Les jeunes ont plus confiance","Le revenu n'a aucun effet"],"answer":"La confiance varie selon l'âge et le revenu","explain":"varier fortement selon… 是结论；「所有人相同」「收入无影响」与原文相反，「年轻人更有信心」是原文没有的方向性判断。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"},{"id":"q-read-b2-0018","level":"B2","skill":"reading","prompt":"[阅读] Faute d'un accord entre les partenaires sociaux, la négociation sur les salaires a été reportée sine die. 问题：Pourquoi la négociation a-t-elle été reportée ?","options":["Par absence d'accord entre les partenaires","Parce que les salaires ont augmenté","Par manque de participants","Par décision du gouvernement"],"answer":"Par absence d'accord entre les partenaires","explain":"faute d'accord ＝「由于未达成一致」，sine die 指无限期推迟；其余原因都没有出现。","source":"阅读 · B2 论述文与报告（compréhension écrite B2 · DELF）"}],"writing":[{"id":"q-writ-b2-0001","level":"B2","skill":"writing","prompt":"写作自评（名词化与冠词），选出正确的一句：","options":["Les résultats de l'enquête mettent en évidence une baisse sensible de la fréquentation.","Les résultats de l'enquête mettent en évidence une baisse sensible du fréquentation.","Les résultats de l'enquête mettent en évidence une baisse sensible de fréquentation.","Les résultats de l'enquête mettent en évidence à une baisse sensible de la fréquentation."],"answer":"Les résultats de l'enquête mettent en évidence une baisse sensible de la fréquentation.","explain":"fréquentation 是阴性名词，缩合冠词应为 de la 而不是 du；de fréquentation 缺定冠词，mettre en évidence 后直接接宾语，不加 à。","source":"写作自评 · B2 报告（production écrite B2）"},{"id":"q-writ-b2-0002","level":"B2","skill":"writing","prompt":"写作自评（原因短语），选出正确的一句：","options":["Faute de données fiables, il est difficile d'évaluer l'impact réel de la mesure.","Faute des données fiables, il est difficile d'évaluer l'impact réel de la mesure.","Faute de données fiables, il est difficile évaluer l'impact réel de la mesure.","Faute de données fiables, il est difficile d'évaluer l'impact réelle de la mesure."],"answer":"Faute de données fiables, il est difficile d'évaluer l'impact réel de la mesure.","explain":"faute de + 名词不带冠词；difficile 后必须接 de + 不定式；impact 是阳性名词，形容词用 réel（réelle 是阴性）。","source":"写作自评 · B2 论证（production écrite B2）"},{"id":"q-writ-b2-0003","level":"B2","skill":"writing","prompt":"写作自评（虚拟式过去时），选出正确的一句：","options":["Il aurait été souhaitable que les parties prenantes soient consultées en amont.","Il aurait été souhaitable que les parties prenantes sont consultées en amont.","Il aurait été souhaitable que les parties prenantes soient consulté en amont.","Il aurait été souhaitable les parties prenantes soient consultées en amont."],"answer":"Il aurait été souhaitable que les parties prenantes soient consultées en amont.","explain":"il aurait été souhaitable que + 虚拟式；sont 是直陈式，过去分词要与阴性复数主语配合（consultées），漏 que 从句不成立。","source":"写作自评 · B2 建议（production écrite B2）"},{"id":"q-writ-b2-0004","level":"B2","skill":"writing","prompt":"写作自评（前置宾语的配合），选出正确的一句：","options":["Non seulement cette politique n'a pas réduit les inégalités, mais elle les a aggravées.","Non seulement cette politique n'a pas réduit les inégalités, mais elle les a aggravé.","Non seulement cette politique n'a pas réduit les inégalités, mais elle a les aggravées.","Non seulement cette politique n'a pas réduit les inégalités, mais elle a aggravé les."],"answer":"Non seulement cette politique n'a pas réduit les inégalités, mais elle les a aggravées.","explain":"avoir 型动词的过去分词要与前置直接宾语 les 配合（aggravées）；aggravé 缺配合，代词必须放在助动词前（a les aggravées、aggravé les 语序错）。","source":"写作自评 · B2 评论（production écrite B2）"},{"id":"q-writ-b2-0005","level":"B2","skill":"writing","prompt":"写作自评（形容词性数配合），选出正确的一句：","options":["Les mesures annoncées, quoique insuffisantes, constituent une première étape.","Les mesures annoncées, quoiqu'insuffisantes, constituent une première étape.","Les mesures annoncées, quoique insuffisant, constituent une première étape.","Les mesures annoncées, malgré insuffisantes, constituent une première étape."],"answer":"Les mesures annoncées, quoique insuffisantes, constituent une première étape.","explain":"quoique 接形容词时不能省音（不写 quoiqu'），形容词要与 mesures 阴性复数配合（insuffisantes），malgré 只能接名词。","source":"写作自评 · B2 让步（production écrite B2）"},{"id":"q-writ-b2-0006","level":"B2","skill":"writing","prompt":"写作自评（书面语惯用式），选出正确的一句：","options":["Il convient de rappeler que ces chiffres ne sauraient être considérés comme définitifs.","Il convient de rappeler que ces chiffres ne sauraient être considéré comme définitifs.","Il convient rappeler que ces chiffres ne sauraient être considérés comme définitifs.","Il convient de rappeler que ces chiffres ne pourraient pas sauraient être considérés comme définitifs."],"answer":"Il convient de rappeler que ces chiffres ne sauraient être considérés comme définitifs.","explain":"il convient de + 不定式；被动态过去分词与复数主语配合（considérés），ne sauraient 本身已表否定，不能再叠 pourraient。","source":"写作自评 · B2 书面语（production écrite B2）"},{"id":"q-writ-b2-0007","level":"B2","skill":"writing","prompt":"写作自评（传闻语气），选出最恰当的一句：","options":["À en croire les derniers indicateurs, la reprise resterait fragile.","À en croire les derniers indicateurs, la reprise restera fragile.","À en croire les derniers indicateurs, la reprise resterait fragiles.","À croire en les derniers indicateurs, la reprise resterait fragile."],"answer":"À en croire les derniers indicateurs, la reprise resterait fragile.","explain":"à en croire 是固定结构，条件式 resterait 表未经确认的判断；restera 失去保留语气，fragiles 配合错误（reprise 阴性单数），à croire en 拆错了固定结构。","source":"写作自评 · B2 报道（production écrite B2）"},{"id":"q-writ-b2-0008","level":"B2","skill":"writing","prompt":"写作自评（loin de），选出正确的一句：","options":["Cette décision, loin de faire l'unanimité, suscite de vives critiques.","Cette décision, loin de faire l'unanimité, suscite des vives critiques.","Cette décision, loin de faire l'unanimité, suscite de vive critiques.","Cette décision, loin faire l'unanimité, suscite de vives critiques."],"answer":"Cette décision, loin de faire l'unanimité, suscite de vives critiques.","explain":"loin de + 不定式；形容词置于名词前时 des 变为 de（de vives critiques），vives 要与阴性复数 critiques 配合。","source":"写作自评 · B2 评论（production écrite B2）"},{"id":"q-writ-b2-0009","level":"B2","skill":"writing","prompt":"写作自评（介词与缩合），选出正确的一句：","options":["Le rapport souligne la nécessité d'adapter les dispositifs aux réalités locales.","Le rapport souligne la nécessité d'adapter les dispositifs à les réalités locales.","Le rapport souligne la nécessité d'adapter les dispositifs des réalités locales.","Le rapport souligne la nécessité adapter les dispositifs aux réalités locales."],"answer":"Le rapport souligne la nécessité d'adapter les dispositifs aux réalités locales.","explain":"à + les 必须缩合为 aux；des 是错误介词（adapter qch à qch），nécessité 后必须接 de + 不定式。","source":"写作自评 · B2 分析（production écrite B2）"},{"id":"q-writ-b2-0010","level":"B2","skill":"writing","prompt":"写作自评（让步与形容词结构），选出正确的一句：","options":["Bien que cette hypothèse soit séduisante, elle reste difficile à vérifier.","Bien que cette hypothèse est séduisante, elle reste difficile à vérifier.","Malgré cette hypothèse soit séduisante, elle reste difficile à vérifier.","Bien que cette hypothèse soit séduisante, elle reste difficile de vérifier."],"answer":"Bien que cette hypothèse soit séduisante, elle reste difficile à vérifier.","explain":"bien que + 虚拟式（soit）；malgré 不能引导从句；difficile 后接 à + 不定式（difficile à vérifier），de 是误搭。","source":"写作自评 · B2 学术表达（production écrite B2）"},{"id":"q-writ-b2-0011","level":"B2","skill":"writing","prompt":"写作自评（虚拟式与赘词 ne），选出正确的一句：","options":["Il est à craindre que cette tendance ne se poursuive au cours des prochaines années.","Il est à craindre que cette tendance se poursuit au cours des prochaines années.","Il est à craindre cette tendance ne se poursuive au cours des prochaines années.","Il est à craindre que cette tendance ne se poursuive au cours des prochaine années."],"answer":"Il est à craindre que cette tendance ne se poursuive au cours des prochaines années.","explain":"il est à craindre que + 虚拟式（se poursuive），ne 是赘词（可省略但不能用直陈式 poursuit）；漏 que 结构不成立，prochaines 要与阴性复数 années 配合。","source":"写作自评 · B2 谨慎判断（production écrite B2）"},{"id":"q-writ-b2-0012","level":"B2","skill":"writing","prompt":"写作自评（quoi que 与 quoique），选出正确的一句：","options":["Quoi qu'il en soit, la question mérite d'être posée.","Quoiqu'il en soit, la question mérite d'être posée.","Quoi qu'il en soit, la question mérite être posée.","Quoi qu'il en soit, la question mérite d'être posé."],"answer":"Quoi qu'il en soit, la question mérite d'être posée.","explain":"quoi que（＝无论什么）分写，quoique（＝虽然）合写，二者不能混用；mériter 后要 de + 不定式，posée 与阴性 question 配合。","source":"写作自评 · B2 书面语（production écrite B2）"},{"id":"q-writ-b2-0013","level":"B2","skill":"writing","prompt":"写作自评（d'aucuns 的用法），选出正确的一句：","options":["D'aucuns estiment que la réforme profitera surtout aux grandes entreprises.","D'aucun estiment que la réforme profitera surtout aux grandes entreprises.","D'aucuns estime que la réforme profitera surtout aux grandes entreprises.","D'aucuns estiment que la réforme profitera surtout à les grandes entreprises."],"answer":"D'aucuns estiment que la réforme profitera surtout aux grandes entreprises.","explain":"书面语 d'aucuns（某些人）是复数形式，动词用 estiment；à + les 必须缩合为 aux。","source":"写作自评 · B2 书面语（production écrite B2）"},{"id":"q-writ-b2-0014","level":"B2","skill":"writing","prompt":"写作自评（固定表达），选出正确的一句：","options":["Toutes proportions gardées, ce résultat reste encourageant.","Toute proportion gardée, ce résultat reste encourageant.","Toutes proportions gardée, ce résultat reste encourageant.","Toutes proportions gardées, ce résultat reste encouragant."],"answer":"Toutes proportions gardées, ce résultat reste encourageant.","explain":"固定表达 toutes proportions gardées 用复数且过去分词配合加 -es；单数形式和 gardée 都改变了固定搭配，encouragant 拼写错误（应为 encourageant）。","source":"写作自评 · B2 固定表达（production écrite B2）"},{"id":"q-writ-b2-0015","level":"B2","skill":"writing","prompt":"写作自评（强调结构），选出正确的一句：","options":["C'est précisément parce que les moyens manquent que la réforme patine.","C'est précisément parce que les moyens manquent, la réforme patine.","C'est précisément parce que les moyens manquent dont la réforme patine.","C'est précisément parce que les moyens manquent qu'la réforme patine."],"answer":"C'est précisément parce que les moyens manquent que la réforme patine.","explain":"c'est… que 强调结构必须成对出现；只写逗号缺 que，用 dont 替代 que，以及 qu' 用在辅音前（应 que la）都是错误。","source":"写作自评 · B2 强调（production écrite B2）"},{"id":"q-writ-b2-0016","level":"B2","skill":"writing","prompt":"写作自评（因果与保留），选出正确的一句：","options":["Dans la mesure où ces données sont incomplètes, toute conclusion serait prématurée.","Dans la mesure où ces données sont incomplètes, toute conclusion serait prématuré.","Dans la mesure que ces données sont incomplètes, toute conclusion serait prématurée.","Dans la mesure où ces données sont incomplète, toute conclusion serait prématurée."],"answer":"Dans la mesure où ces données sont incomplètes, toute conclusion serait prématurée.","explain":"固定搭配 dans la mesure où（不用 que）；données 是阴性复数→incomplètes，conclusion 是阴性→prématurée。","source":"写作自评 · B2 论证（production écrite B2）"}],"speaking":[{"id":"q-speak-b2-0001","level":"B2","skill":"speaking","prompt":"口语自评（让步后转折），选出正确的一句：","options":["S'il est vrai que la mesure a des effets positifs, il n'en demeure pas moins qu'elle reste coûteuse.","S'il est vrai que la mesure a des effets positifs, il n'en demeure pas moins qu'elle reste coûteux.","S'il est vrai que la mesure a des effets positifs, il n'en demeure pas qu'elle reste coûteuse.","S'il est vrai que la mesure a des effets positifs, il ne demeure pas moins qu'elle reste coûteuse."],"answer":"S'il est vrai que la mesure a des effets positifs, il n'en demeure pas moins qu'elle reste coûteuse.","explain":"固定表达 il n'en demeure pas moins que 三部分都不能少（n'、en、moins）；coûteux 要与阴性 mesure 配合为 coûteuse。","source":"口语自评 · B2 辩论（production orale B2）"},{"id":"q-speak-b2-0002","level":"B2","skill":"speaking","prompt":"口语自评（承认事实并保留），选出正确的一句：","options":["Je conviens que la situation est préoccupante, encore faut-il éviter toute surenchère.","Je conviens de que la situation est préoccupante, encore faut-il éviter toute surenchère.","Je conviens que la situation est préoccupante, encore faut-il éviter de toute surenchère.","Je conviens que la situation est préoccupe, encore faut-il éviter toute surenchère."],"answer":"Je conviens que la situation est préoccupante, encore faut-il éviter toute surenchère.","explain":"convenir que 不加 de；éviter 直接接名词宾语（不加 de）；préoccupante 是形容词，préoccupe 是动词变位。","source":"口语自评 · B2 辩论（production orale B2）"},{"id":"q-speak-b2-0003","level":"B2","skill":"speaking","prompt":"口语自评（礼貌提醒重点），选出正确的一句：","options":["Je me permets d'attirer votre attention sur un point qui me paraît essentiel.","Je me permets d'attirer votre attention à un point qui me paraît essentiel.","Je me permets attirer votre attention sur un point qui me paraît essentiel.","Je me permets d'attirer votre attention sur un point qui me paraît essentielle."],"answer":"Je me permets d'attirer votre attention sur un point qui me paraît essentiel.","explain":"attirer l'attention sur qch 是固定搭配；se permettre de + 不定式（漏 de 不成立）；point 是阳性，表语用 essentiel。","source":"口语自评 · B2 会议（production orale B2）"},{"id":"q-speak-b2-0004","level":"B2","skill":"speaking","prompt":"口语自评（表达遗憾），选出正确的一句：","options":["J'aurais préféré que nous en discutions plus tôt.","J'aurais préféré que nous en discutons plus tôt.","J'aurais préféré que nous en discuterions plus tôt.","J'aurais préféré de discuter plus tôt."],"answer":"J'aurais préféré que nous en discutions plus tôt.","explain":"préférer que + 虚拟式（discutions）；discutons 是直陈式，discuterions 是条件式，préférer de + 不定式不是这个结构的搭配。","source":"口语自评 · B2 表达态度（production orale B2）"},{"id":"q-speak-b2-0005","level":"B2","skill":"speaking","prompt":"口语自评（学术语域），选出正确的一句：","options":["Force est de reconnaître que les données disponibles ne permettent pas de trancher.","Force est de reconnaître que les données disponibles ne permettent pas trancher.","Force de reconnaître que les données disponibles ne permettent pas de trancher.","Force est de reconnaître que les données disponibles ne permettent pas à trancher."],"answer":"Force est de reconnaître que les données disponibles ne permettent pas de trancher.","explain":"固定结构 force est de + 不定式；permettre de + 不定式（漏 de 不成立），à 是误搭；省掉 est 则整个结构不成立。","source":"口语自评 · B2 学术口语（production orale B2）"},{"id":"q-speak-b2-0006","level":"B2","skill":"speaking","prompt":"口语自评（有条件的同意），选出正确的一句：","options":["J'y souscrirais volontiers, à condition que le calendrier soit respecté.","J'y souscrirais volontiers, à condition que le calendrier est respecté.","J'y souscrirais volontiers, à condition du calendrier soit respecté.","J'y souscrirais volontiers, à condition que le calendrier soit respecter."],"answer":"J'y souscrirais volontiers, à condition que le calendrier soit respecté.","explain":"à condition que + 虚拟式（soit respecté）；est 是直陈式，du 不能代替 que，respecter 是原形（应过去分词 respecté）。","source":"口语自评 · B2 谈判（production orale B2）"},{"id":"q-speak-b2-0007","level":"B2","skill":"speaking","prompt":"口语自评（汇报数据），选出正确的一句：","options":["Il ressort de l'analyse que la tendance s'est inversée depuis 2023.","Il ressort de l'analyse que la tendance s'est inversé depuis 2023.","Il ressort l'analyse que la tendance s'est inversée depuis 2023.","Il ressort de l'analyse de la tendance s'est inversée depuis 2023."],"answer":"Il ressort de l'analyse que la tendance s'est inversée depuis 2023.","explain":"ressortir de qch（从……得出）用 de；过去分词与阴性 tendance 配合（inversée）；从句必须由 que 引导。","source":"口语自评 · B2 汇报（production orale B2）"},{"id":"q-speak-b2-0008","level":"B2","skill":"speaking","prompt":"口语自评（缓和批评），选出正确的一句：","options":["Je ne remets pas en cause vos compétences, mais la méthode employée me paraît discutable.","Je ne remets pas en cause à vos compétences, mais la méthode employée me paraît discutable.","Je ne remets pas en cause vos compétences, mais la méthode employée me paraît discutez.","Je ne remets en cause pas vos compétences, mais la méthode employée me paraît discutable."],"answer":"Je ne remets pas en cause vos compétences, mais la méthode employée me paraît discutable.","explain":"remettre en cause 直接接宾语（不加 à）；discutable 是形容词（discutez 是变位动词）；ne…pas 要夹住变位动词 remets。","source":"口语自评 · B2 反馈（production orale B2）"},{"id":"q-speak-b2-0009","level":"B2","skill":"speaking","prompt":"口语自评（组织论证），选出正确的一句：","options":["Deux éléments méritent d'être soulignés : d'une part la rapidité, d'autre part le coût.","Deux éléments méritent d'être souligné : d'une part la rapidité, d'autre part le coût.","Deux éléments méritent être soulignés : d'une part la rapidité, d'autre part le coût.","Deux éléments méritent d'être soulignés : d'un part la rapidité, d'autre part le coût."],"answer":"Deux éléments méritent d'être soulignés : d'une part la rapidité, d'autre part le coût.","explain":"mériter d'être + 过去分词，且过去分词与 éléments 阳性复数配合（soulignés）；漏 d' 不成立；固定表达是 d'une part。","source":"口语自评 · B2 论述（production orale B2）"},{"id":"q-speak-b2-0010","level":"B2","skill":"speaking","prompt":"口语自评（让步后的补充），选出正确的一句：","options":["Certes, les critiques sont fondées ; encore convient-il d'en mesurer la portée.","Certes, les critiques sont fondées ; encore convient-il de mesurer en la portée.","Certes, les critiques sont fondées ; encore convient-il d'en mesurer le portée.","Certes, les critiques sont fondés ; encore convient-il d'en mesurer la portée."],"answer":"Certes, les critiques sont fondées ; encore convient-il d'en mesurer la portée.","explain":"代词 en 必须放在不定式前（d'en mesurer）；portée 是阴性（la portée）；critiques 是阴性复数，过去分词配合为 fondées。","source":"口语自评 · B2 辩论（production orale B2）"},{"id":"q-speak-b2-0011","level":"B2","skill":"speaking","prompt":"口语自评（正式澄清请求），选出正确的一句：","options":["Pourriez-vous expliciter ce que vous entendez par « gouvernance » ?","Pourriez-vous expliciter ce que vous entendez de « gouvernance » ?","Pourriez-vous expliciter que vous entendez par « gouvernance » ?","Pourriez-vous expliciter ce que vous entendez à « gouvernance » ?"],"answer":"Pourriez-vous expliciter ce que vous entendez par « gouvernance » ?","explain":"entendre par qch 是固定搭配；de 和 à 都是误搭，漏 ce 会使从句缺宾语。","source":"口语自评 · B2 澄清（production orale B2）"},{"id":"q-speak-b2-0012","level":"B2","skill":"speaking","prompt":"口语自评（表明优先立场），选出正确的一句：","options":["En ce qui me concerne, la priorité devrait être donnée à la prévention.","En ce qui me concerne, la priorité devrait donner à la prévention.","En ce qui concerne à moi, la priorité devrait être donnée à la prévention.","En ce qui me concerne, la priorité devrait être donnée de la prévention."],"answer":"En ce qui me concerne, la priorité devrait être donnée à la prévention.","explain":"en ce qui me concerne 是固定表达；被动态必须保留 être（devrait être donnée），donner qch à qch 的介词是 à（不是 de）。","source":"口语自评 · B2 表达立场（production orale B2）"},{"id":"q-speak-b2-0013","level":"B2","skill":"speaking","prompt":"口语自评（转述并保留距离），选出正确的一句：","options":["Selon certaines sources, le projet aurait été abandonné, ce que la direction n'a pas confirmé.","Selon certaines sources, le projet aurait été abandonné, ce qui la direction n'a pas confirmé.","Selon certaines sources, le projet aurait été abandonné, ce que la direction n'a pas confirmée.","Selon certaines sources, le projet aurait été abandonné, que la direction n'a pas confirmé."],"answer":"Selon certaines sources, le projet aurait été abandonné, ce que la direction n'a pas confirmé.","explain":"关系代词在从句中作直接宾语要用 ce que（ce qui 只能作主语）；n'a pas confirmé 的宾语是中性代词 ce，过去分词不配合；漏 ce 则关系从句不成立。","source":"口语自评 · B2 汇报（production orale B2）"},{"id":"q-speak-b2-0014","level":"B2","skill":"speaking","prompt":"口语自评（委婉修正对方），选出正确的一句：","options":["Si je puis me permettre, il me semble que la question est légèrement différente.","Si je peux me permettre, il me semble que la question est légèrement différent.","Si je puis me permettre, il me semble que la question est légèrement différent.","Si je puis permettre, il me semble que la question est légèrement différente."],"answer":"Si je puis me permettre, il me semble que la question est légèrement différente.","explain":"permettre 是代词式用法（se permettre de）；question 是阴性，表语用 différente；漏 me 结构不成立。","source":"口语自评 · B2 讨论（production orale B2）"},{"id":"q-speak-b2-0015","level":"B2","skill":"speaking","prompt":"口语自评（结束发言），选出正确的一句：","options":["Voilà, en substance, ce que je souhaitais dire sur ce point.","Voilà, en substance, ce que je souhaitais dire à ce point.","Voilà, en substance, ce dont je souhaitais dire sur ce point.","Voilà, en substance, ce que je souhaitais parler sur ce point."],"answer":"Voilà, en substance, ce que je souhaitais dire sur ce point.","explain":"dire 直接接宾语用 ce que；sur ce point 表「关于这一点」（à ce point 意为「到这种程度」），parler de 不能替换 dire。","source":"口语自评 · B2 发言（production orale B2）"},{"id":"q-speak-b2-0016","level":"B2","skill":"speaking","prompt":"口语自评（谨慎结论），选出正确的一句：","options":["On ne saurait tirer de conclusion définitive d'un échantillon aussi restreint.","On ne saurait tirer de conclusion définitive d'un échantillon aussi restreinte.","On ne saurait tirer de conclusion définitive à un échantillon aussi restreint.","On ne saurait pas tirer de conclusion définitive d'un échantillon aussi restreint."],"answer":"On ne saurait tirer de conclusion définitive d'un échantillon aussi restreint.","explain":"échantillon 是阳性，形容词用 restreint；tirer de qch（从……得出）用 de 而不是 à；ne saurait 本身已含否定，不能再加 pas。","source":"口语自评 · B2 学术口语（production orale B2）"}]}}.B2;
